insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$matutina$q$, $q$https://www.diariomunicipal.com.br/amm-mg/materia/DCD67BD3 (Dec. 080/2021) ; https://www.diariomunicipal.com.br/amm-mg/materia/F70CE0A1 (Dec. 057/2021)$q$, $q$Atos oficiais de Matutina: domínio público (Lei 9.610/1998, art. 8º, IV). Perímetro urbano aproximado e R. Omar Carneiro: derivados do OpenStreetMap (ODbL 1.0, © colaboradores do OpenStreetMap).$q$, 2, $q$Dec. 080/2021: no perímetro urbano, proibida a circulação de veículos com carga superior a 15 t (lido como capacidade de carga), salvo entrega/carga e descarga no perímetro. Dec. 057/2021: o mesmo na R. Omar Carneiro (entre a R. João Mulato e a R. Moacir Franco). Perímetro urbano sem delimitação no ato: polígono aproximado do tecido urbano da sede.$q$);
